+                assert!(
+                    sent.elapsed() < Duration::from_millis(100),
+                    "glyph did not paint promptly"
+                );
+                std::thread::sleep(Duration::from_micros(100));
+            }
+            latencies.push(sent.elapsed().as_micros());
+        }
+        sender.join().unwrap();
+        latencies.sort_unstable();
+        measured.push((
+            hz,
+            phase.elapsed().as_micros(),
+            latencies[16],
+            latencies[30],
+            latencies[31],
+        ));
